#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODE_LEN 100
#define MAX_NODE_COUNT 100

typedef struct node {
    char *name;
    struct node *next;
} node;

node *head;

void add_node(char *name) {
    node *new_node = malloc(sizeof(node));
    new_node->name = malloc(MAX_NODE_LEN);
    strcpy(new_node->name, name);
    new_node->next = NULL;

    if (head == NULL) {
        head = new_node;
    } else {
        node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void print_chain() {
    node *current = head;
    while (current != NULL) {
        printf("%s\n", current->name);
        current = current->next;
    }
}

int main() {
    char *names[] = {
        "qgv",
        "qxc",
        "bbb",
        "ccc",
        "aaa",
        "ddd"
    };

    for (int i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
        add_node(names[i]);
    }

    print_chain();
    return 0;
}

